<?php foreach($sellerOrders as $sellerOrder):?><section class="panel"><div class="panel-head"><div><small><?=e($sellerOrder['code'])?></small><h3><?=e($sellerOrder['store_name'])?></h3></div><?php $status=$sellerOrder['status'];require dirname(__DIR__,2).'/components/dashboard/status-badge.php';?></div><div class="table-wrap"><table><thead><tr><th>Produto</th><th>SKU</th><th>Qtd.</th><th>Total</th></tr></thead><tbody><?php foreach($sellerOrder['items'] as $item):?><tr><td><?=e($item['product_name'])?></td><td><?=e($item['sku'])?></td><td><?=(int)$item['quantity']?></td><td>R$ <?=number_format((float)$item['total'],2,',','.')?></td></tr><?php endforeach;?></tbody></table></div><p><strong>Remessa:</strong> <?=e($sellerOrder['service_name']?:'Não definida')?> · <?=e($sellerOrder['carrier_name']?:'Transportadora não definida')?><?php if($sellerOrder['tracking_code']):?> · Rastreio <?=e($sellerOrder['tracking_code'])?><?php endif;?></p><?php if($trackingConfigured&&!empty($sellerOrder['external_id'])):?><form method="post" action="<?=e(url('/admin/pedidos/'.$order['code'].'/remessas/'.$sellerOrder['shipment_id'].'/sincronizar'))?>"><?=csrf_field()?><button class="button button--secondary">Sincronizar rastreamento</button></form><?php endif;?></section><?php endforeach;?>
